# LESSON 1: THE DIVINE FLOW
# ============================================================
LESSONS.append(dict(
    num=1, slug='the-divine-flow', title='The Divine Flow',
    part=3, subtitle='Serving in Christ',
    section='A', section_name="Living in the Spirit's Power",
    opening='Think of a time you felt a sudden, unexplained pull to help, comfort or speak to someone you barely knew. What did you do with that prompting, and what stopped you or moved you?',
    ks_ref='Philemon 1:6',
    ks_text='That the sharing of your faith may become effective by the acknowledgment of every good thing which is in you in Christ Jesus.',
    ks_note='Read this slowly before moving on. The flow this lesson describes starts here: with acknowledging what is already true, not with manufacturing something new.',
    core='God’s love is not something you work up. It is something already placed in you by the Holy Spirit, waiting to be acknowledged and released.',
    teaching=[
        ('h3', 'Something already there, not something to build'),
        ('p', 'Every believer already has "every good thing" in Christ Jesus placed within them. The starting point is not manufacturing love or compassion through willpower; it is recognising what the Holy Spirit has already deposited. Andrew Wommack describes this first step as being like "ringing a bell" rather than building something from nothing.'),
        ('scripture', '1 John 4:7-8', 'Beloved, let us love one another, for love is of God; and everyone who loves is born of God and knows God. He who does not love does not know God, for God is love.'),
        ('p', 'God’s love, once poured into the heart, is meant to move outward, not stay contained. This is not a suggestion for especially spiritual believers; it is the ordinary nature of anyone born of God.'),
        ('h3', 'Testing the source: 1 Corinthians 13'),
        ('p', 'Not every strong feeling toward another person is the divine flow. Supernatural compassion can be told apart from ordinary sentiment, sympathy, or self-interested attraction by testing it against the description of love in 1 Corinthians 13.'),
        ('scripture', '1 Corinthians 13:4-5', 'Love suffers long and is kind; love does not envy; love does not parade itself, is not puffed up; does not behave rudely, does not seek its own, is not provoked, thinks no evil.'),
        ('callout', 'depth', 'Wommack’s teaching draws a careful line between emotional sympathy and the divine flow. Sympathy can be self-focused; it often centres on how the situation makes you feel. The divine flow is always aimed outward, toward the other person’s genuine good, and it is tested by whether it actually looks like 1 Corinthians 13 in practice, not merely by its intensity.'),
        ('h3', 'Christ’s pattern: compassion, then action'),
        ('p', 'Jesus modelled the divine flow constantly. Before He acted, He felt something first.'),
        ('scripture', 'Matthew 14:14', 'And Jesus went out and saw a great multitude; and He was moved with compassion for them, and healed their sick.'),
        ('p', 'Feeling compassion is the start of the flow, not its completion. The flow is not finished until it is released in a word, a touch, or an action, the way Jesus released His compassion in healing, and the way He released forgiveness itself from the cross.'),
        ('scripture', 'Luke 23:34', 'Then Jesus said, "Father, forgive them, for they do not know what they do."'),
        ('callout', 'note', 'The flow is designed to reach the other person, not stop at recognition. Withholding the word or deed once prompted leaves the flow incomplete, whatever was genuinely felt in the moment.'),
    ],
    kdq=[
        'Describe a specific moment when you sensed a prompting to show love or compassion to someone. What did you do?',
        'How would you use 1 Corinthians 13:4-8 to test whether a feeling is the divine flow or something else?',
        'Philemon 1:6 says "every good thing" is already in you in Christ. What does that change about how you approach showing love to others?',
        'What is one prompting you have felt recently but not yet acted on? What would completing that flow look like this week?',
    ],
    gdq=[
        'Why do you think Wommack compares acknowledging what is already in you to "ringing a bell" rather than "building" something new?',
        'Share a time someone’s compassion toward you clearly went beyond ordinary kindness. What made it feel supernatural?',
        'What stops believers most often from completing the flow once they sense it: fear, self-doubt, timing, or something else?',
        'How does knowing love is already in you change the pressure you might feel to "perform" ministry to others?',
    ],
    app_intro='The divine flow is not a truth to admire from a distance; it is meant to move through you into someone else’s life this week.',
    app=[
        ('Personal life', 'Before your next opportunity to help someone, pause and name what you are sensing: is this compassion that matches 1 Corinthians 13, or something else? Practise the discernment, not just the doing.'),
        ('Church community', 'Choose one prompting you have been sitting on and follow it through in a word, a touch, or a practical act, however small, for someone in your church community this week.'),
        ('Difficult seasons', 'When compassion feels hard to access in a difficult season of your own, read through one Gospel account of Jesus healing or helping someone and let His pattern, compassion first, then action, recalibrate your own.'),
        ('Scripture to carry', 'Memorise Philemon 1:6: "That the sharing of your faith may become effective by the acknowledgment of every good thing which is in you in Christ Jesus." Carry it as the reminder that the flow starts with acknowledgment, not effort.'),
    ],
    cards=[
        dict(front='What is the "divine flow"?', ref='Philemon 1:6', back_type='verse',
             back='"That the sharing of your faith may become effective by the acknowledgment of every good thing which is in you in Christ Jesus."', back_ref='Philemon 1:6'),
        dict(front='What is God’s own nature, according to 1 John?', ref='1 John 4:8', back_type='verse',
             back='"He who does not love does not know God, for God is love."', back_ref='1 John 4:8'),
        dict(front='What test distinguishes divine compassion from self-interest?', ref='1 Corinthians 13:4', back_type='verse',
             back='"Love suffers long and is kind; love does not envy; love does not parade itself, is not puffed up."', back_ref='1 Corinthians 13:4'),
        dict(front='What did Jesus feel before He healed the multitudes?', ref='Matthew 14:14', back_type='verse',
             back='"And Jesus went out and saw a great multitude; and He was moved with compassion for them, and healed their sick."', back_ref='Matthew 14:14'),
        dict(front='What did Jesus pray for those crucifying Him?', ref='Luke 23:34', back_type='verse',
             back='"Then Jesus said, ‘Father, forgive them, for they do not know what they do.’"', back_ref='Luke 23:34'),
        dict(front='Why do we love, according to John?', ref='1 John 4:19', back_type='verse',
             back='"We love Him because He first loved us."', back_ref='1 John 4:19'),
    ],
))

